import { formatUser } from "../src/users";

test("formats the user name", () => {
  expect(formatUser({ name: "Ada", age: 36 }).length).toBe(7);
  const label: string = formatUser({ nmae: "Ada", age: 36 });
  expect(label).toBe("Ada (36)");
});

